import type { list, parseJson, record, text } from "./wire.ts";

export async function probeRenderedSchema(
  read: typeof record,
  parse: typeof parseJson,
  asText: typeof text,
  asList: typeof list,
) {
  const assert: typeof import("node:assert/strict") =
    process.getBuiltinModule("node:assert/strict");
  const fs = process.getBuiltinModule("node:fs");
  const cp = process.getBuiltinModule("node:child_process");
  const input = read(parse(fs.readFileSync(0, "utf8")));
  const gatewayArgs = asList(input.gatewayArgs).map(asText);
  const harness = asText(input.harness);
  const workspaceNodeId = asText(input.workspaceNodeId);
  const { startupMs, harnessRunMs, validateMs: validationDeadline } = input;
  assert.ok(
    typeof startupMs === "number" &&
      typeof harnessRunMs === "number" &&
      typeof validationDeadline === "number",
  );
  const validateMs = validationDeadline;
  const startupDeadline = startupMs;
  const model = "openai/runtime-image-schema";
  function validate(path: string) {
    const home = fs.mkdtempSync("/tmp/oce-config-validate-");
    const result = cp.spawnSync("node", ["/app/openclaw.mjs", "config", "validate", "--json"], {
      env: { PATH: process.env.PATH, HOME: home, OPENCLAW_CONFIG_PATH: path },
      encoding: "utf8",
      timeout: validateMs,
      maxBuffer: 1024 * 1024,
    });
    const report = read(parse(result.stdout));
    return { status: result.status, valid: report.valid, issues: report.issues ?? [] };
  }
  function run(
    args: string[],
    env: NodeJS.ProcessEnv,
    readinessUrl?: string,
    limitMs = startupDeadline,
  ) {
    const child = cp.spawn("node", args, {
      env: { PATH: process.env.PATH, HOME: "/home/node", ...env },
      detached: true,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let output = "";
    child.stdout.on("data", (value: Buffer) => {
      output += value.toString();
    });
    child.stderr.on("data", (value: Buffer) => {
      output += value.toString();
    });
    let ready = false;
    let stopped = false;
    function killGroup(signal: NodeJS.Signals) {
      if (child.pid === undefined) {
        return;
      }
      try {
        process.kill(-child.pid, signal);
      } catch (error) {
        if (!(error instanceof Error && "code" in error && error.code === "ESRCH")) {
          throw error;
        }
      }
    }
    return new Promise<{
      code: number | null;
      signal: NodeJS.Signals | null;
      output: string;
      ready: boolean;
    }>((resolve, reject) => {
      // Kill the owned process group: a launcher can leave native children holding
      // stdout open even after it exits. Container removal is the outer safeguard.
      const deadline = setTimeout(() => killGroup("SIGKILL"), limitMs);
      child.once("error", reject);
      child.once("exit", () => {
        stopped = true;
        killGroup("SIGKILL");
      });
      child.once("close", (code, signal) => {
        clearTimeout(deadline);
        resolve({ code, signal, output, ready });
      });
      if (readinessUrl) {
        (async () => {
          while (!stopped) {
            try {
              ready = (await fetch(readinessUrl, { signal: AbortSignal.timeout(1000) })).ok;
            } catch {
              // The Gateway can refuse connections until its readiness listener starts.
            }
            if (ready) {
              child.kill("SIGTERM");
              return;
            }
            await new Promise((resolve) => setTimeout(resolve, 100));
          }
        })().catch(reject);
      }
    });
  }
  fs.mkdirSync("/tmp/gateway", { recursive: true });
  fs.copyFileSync("/etc/openclaw/openclaw.json", "/tmp/gateway/base.json");
  const gatewayBase = read(parse(fs.readFileSync("/tmp/gateway/base.json", "utf8")));
  const agents = read(gatewayBase.agents ?? {});
  const defaults = read(agents.defaults ?? {});
  defaults.workspace = "/tmp/runtime-image-provider-workspace";
  agents.defaults = defaults;
  gatewayBase.agents = agents;
  fs.writeFileSync("/tmp/gateway/base.json", JSON.stringify(gatewayBase));
  const gatewayEnvironment = {
    OPENCLAW_CONFIG_PATH: "/tmp/gateway/base.json",
    OPENCLAW_STATE_DIR: "/home/node/.openclaw",
    OPENCLAW_GATEWAY_PORT: "18789",
    OPENCLAW_GATEWAY_PASSWORD: "openclaw-runtime-image-schema-password",
    OPENCLAW_WORKSPACE_NODE_ID: workspaceNodeId,
    OPENCLAW_NATIVE_WORKER_PROFILE: "dedicated-native",
  };
  const gatewayRun = await run(
    ["-e", ...gatewayArgs],
    gatewayEnvironment,
    "http://127.0.0.1:18789/readyz",
  );
  const gatewayConfig = "/home/node/.openclaw/openclaw.json";
  // A container restart reuses the writable admin Configuration, including the
  // profile generated by the first wrapper. It must still start the native Gateway.
  const gatewayRestart = await run(
    ["-e", ...gatewayArgs],
    {
      ...gatewayEnvironment,
      OPENCLAW_CONFIG_PATH: gatewayConfig,
    },
    "http://127.0.0.1:18789/readyz",
  );
  const generatedConfiguration = fs.readFileSync(gatewayConfig, "utf8");
  const conflictingConfig = read(parse(generatedConfiguration));
  const profiles = read(read(conflictingConfig.cloudWorkers).profiles);
  const settings = read(read(profiles["dedicated-native"]).settings);
  settings.device = (workspaceNodeId[0] === "a" ? "b" : "a") + workspaceNodeId.slice(1);
  fs.writeFileSync(gatewayConfig, JSON.stringify(conflictingConfig));
  // Restart tolerance must not admit a profile bound to a different worker.
  const conflictingRestart = await run(["-e", ...gatewayArgs], {
    ...gatewayEnvironment,
    OPENCLAW_CONFIG_PATH: gatewayConfig,
  });
  fs.writeFileSync(gatewayConfig, generatedConfiguration);
  const probe = JSON.stringify({
    auth: { probes: { results: [{ provider: "openai", model, source: "env", status: "ok" }] } },
  });
  fs.writeFileSync(
    "/tmp/probe.cjs",
    [
      'const cp = require("node:child_process");',
      "const spawnSync = cp.spawnSync;",
      "cp.spawnSync = (command, args, options) => Array.isArray(args) && args.includes('--probe')",
      "  ? { status: 0, stdout: " +
        JSON.stringify(probe) +
        " } : spawnSync(command, args, options);",
    ].join("\n"),
  );
  const harnessRun = await run(
    ["-r", "/tmp/probe.cjs", "-e", harness],
    {
      TMPDIR: "/tmp/openclaw-native-worker",
      OPENCLAW_NATIVE_WORKER_CAPACITY: "8",
      OPENCLAW_NODE_STATE_DIR: "/home/node/.openclaw-node",
      OPENCLAW_NODE_SETUP_CODE: "runtime-image-schema-setup-code",
      OPENCLAW_WORKSPACE_DIR: "/tmp/runtime-image-provider-workspace",
      OPENCLAW_NATIVE_INFERENCE_CONFIG: JSON.stringify({
        models: {
          providers: {
            openai: {
              baseUrl: "https://api.openai.com/v1",
              apiKey: { source: "env", provider: "model", id: "OPENAI_API_KEY" },
              models: [
                {
                  id: "runtime-image-schema",
                  name: "runtime-image-schema",
                  api: "openai-responses",
                  contextWindow: 128000,
                  maxTokens: 8192,
                },
              ],
            },
          },
        },
        secrets: { providers: { model: { source: "env", allowlist: ["OPENAI_API_KEY"] } } },
      }),
      OPENCLAW_RUNTIME_STATUS_PORT: "18791",
      OPENCLAW_HARNESS_MODEL: model,
      OPENCLAW_HARNESS_PROVIDER: "openai",
      OPENCLAW_HARNESS_CREDENTIAL_ENV: "OPENAI_API_KEY",
      OPENAI_API_KEY: "sk-openclaw-runtime-image-schema-synthetic",
      OPENCLAW_HARNESS_PROBE_CONFIG: JSON.stringify({ agents: { defaults: { model } } }),
    },
    undefined,
    harnessRunMs,
  );
  const harnessConfig = "/home/node/.openclaw-node/openclaw.json";
  process.stdout.write(
    JSON.stringify({
      gateway: {
        ...gatewayRun,
        restart: gatewayRestart,
        conflictingRestart,
        config: parse(fs.readFileSync(gatewayConfig, "utf8")),
        validation: validate(gatewayConfig),
      },
      harness: {
        ...harnessRun,
        config: parse(fs.readFileSync(harnessConfig, "utf8")),
        validation: validate(harnessConfig),
      },
    }),
  );
}
